```typescript
import type { ElectrobunConfig } from "electrobun";

export default {
  app: {
    name: "Cross Platform App",
    identifier: "com.example.cross-platform",
    version: "1.0.0",
  },
  build: {
    mac: {
      bundleCEF: true,
      bundleWGPU: true,
